import os
import time
import json
import socket
import logging
from datetime import datetime, timezone
from typing import Any, Dict, Iterable, List, Optional

import boto3
from botocore.exceptions import ClientError


class CorrelationIdFilter(logging.Filter):
    def __init__(self, correlation_id: str) -> None:
        super().__init__()
        self.correlation_id = correlation_id

    def filter(self, record: logging.LogRecord) -> bool:
        if not hasattr(record, "correlation_id"):
            record.correlation_id = self.correlation_id
        return True


class CloudWatchCorrelationLogHandler(logging.Handler):
    def __init__(
        self,
        log_group_name: str,
        log_stream_name: str,
        region_name: Optional[str] = None,
        create_if_missing: bool = True,
    ) -> None:
        super().__init__()
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
        self.client = boto3.client("logs", region_name=self.region_name)
        self._create_if_missing = create_if_missing

        if self._create_if_missing:
            self._ensure_group_and_stream()

    def _ensure_group_and_stream(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except ClientError as e:
            if e.response["Error"]["Code"] != "ResourceAlreadyExistsException":
                raise

        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except ClientError as e:
            if e.response["Error"]["Code"] != "ResourceAlreadyExistsException":
                raise

    def emit(self, record: logging.LogRecord) -> None:
        try:
            event = self._record_to_event(record)
            self.client.put_log_events(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
                logEvents=[event],
            )
        except Exception:
            self.handleError(record)

    def _record_to_event(self, record: logging.LogRecord) -> Dict[str, Any]:
        payload = {
            "timestamp": datetime.fromtimestamp(record.created, tz=timezone.utc).isoformat(),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
            "correlation_id": getattr(record, "correlation_id", None),
            "pathname": record.pathname,
            "lineno": record.lineno,
            "function": record.funcName,
            "process": record.process,
            "thread": record.thread,
            "host": socket.gethostname(),
        }

        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)

        return {
            "timestamp": int(record.created * 1000),
            "message": json.dumps(payload, default=str),
        }


def get_correlation_logger(
    name: str,
    correlation_id: str,
    log_group_name: str,
    log_stream_name: Optional[str] = None,
    region_name: Optional[str] = None,
    level: int = logging.INFO,
) -> logging.Logger:
    logger = logging.getLogger(name)
    logger.setLevel(level)
    logger.propagate = False

    stream_name = log_stream_name or f"{socket.gethostname()}-{int(time.time())}"

    handler_exists = any(
        isinstance(h, CloudWatchCorrelationLogHandler)
        and h.log_group_name == log_group_name
        and h.log_stream_name == stream_name
        for h in logger.handlers
    )
    if not handler_exists:
        handler = CloudWatchCorrelationLogHandler(
            log_group_name=log_group_name,
            log_stream_name=stream_name,
            region_name=region_name,
        )
        logger.addHandler(handler)

    filter_exists = any(
        isinstance(f, CorrelationIdFilter) and f.correlation_id == correlation_id
        for f in logger.filters
    )
    if not filter_exists:
        logger.addFilter(CorrelationIdFilter(correlation_id))

    return logger


def write_application_log(
    correlation_id: str,
    message: str,
    level: str = "INFO",
    log_group_name: str = "application-logs",
    log_stream_name: Optional[str] = None,
    logger_name: str = "app",
    region_name: Optional[str] = None,
    extra_fields: Optional[Dict[str, Any]] = None,
) -> None:
    logger = get_correlation_logger(
        name=logger_name,
        correlation_id=correlation_id,
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
        level=getattr(logging, level.upper(), logging.INFO),
    )

    extra = {"correlation_id": correlation_id}
    if extra_fields:
        extra.update(extra_fields)

    log_method = getattr(logger, level.lower(), logger.info)
    log_method(message, extra=extra)


def write_batch_application_logs(
    correlation_id: str,
    events: Iterable[Dict[str, Any]],
    log_group_name: str,
    log_stream_name: str,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client(
        "logs",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
    )

    try:
        client.create_log_group(logGroupName=log_group_name)
    except ClientError as e:
        if e.response["Error"]["Code"] != "ResourceAlreadyExistsException":
            raise

    try:
        client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)
    except ClientError as e:
        if e.response["Error"]["Code"] != "ResourceAlreadyExistsException":
            raise

    now_ms = int(time.time() * 1000)
    log_events: List[Dict[str, Any]] = []

    for i, event in enumerate(events):
        payload = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "correlation_id": correlation_id,
            "host": socket.gethostname(),
            **event,
        }
        log_events.append(
            {
                "timestamp": event.get("timestamp_ms", now_ms + i),
                "message": json.dumps(payload, default=str),
            }
        )

    log_events.sort(key=lambda e: e["timestamp"])

    response = client.put_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name,
        logEvents=log_events,
    )
    return response
